/**
 * Shop API - 文创商城接口
 * 
 * 接口列表:
 * - getProducts: 获取所有商品 (支持筛选)
 * - getProductDetail: 获取单个商品详情
 * - getCategories: 获取商品分类
 */

import request from './request.js'

export default {
  /**
   * 获取所有商品
   * @param {object} params - 查询参数 { category, search, page, limit }
   */
  getProducts(params = {}) {
    return request.get('/shop', { params })
  },

  /**
   * 获取单个商品详情
   * @param {string} id - 商品ID
   */
  getProductDetail(id) {
    return request.get(`/shop/${id}`)
  },

  /**
   * 获取商品分类
   */
  getCategories() {
    return request.get('/shop/categories')
  }
}
